WITH filtered AS (SELECT *, CASE WHEN city = 'Singapore' THEN 1 ELSE 0 END AS is_singapore FROM suppliers WHERE city = 'Singapore') SELECT id, supplier_name, city, FIRST_VALUE(is_singapore, TRUE) OVER (PARTITION BY city ORDER BY is_singapore, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_is_singapore, RANK() OVER (PARTITION BY city, country ORDER BY rating NULLS FIRST) AS rating_rank FROM filtered
